package com.bobbuy.livecart;

import com.bobbuy.model.*;import com.bobbuy.repository.*;import com.bobbuy.security.*;import com.bobbuy.service.ProductSaleService;import com.bobbuy.service.LlmGateway;import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.*;import java.sql.ResultSet;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import static com.bobbuy.livecart.LiveCartModels.*;

@Service
public class LiveCartService {
 private final JdbcClient db; private final UserRepository users; private final ProductRepository products; private final ProductSaleService sales; private final LlmGateway llm; private final ObjectMapper json;
 public LiveCartService(JdbcClient db,UserRepository users,ProductRepository products,ProductSaleService sales,LlmGateway llm,ObjectMapper json){this.db=db;this.users=users;this.products=products;this.sales=sales;this.llm=llm;this.json=json;}
 private long customer(Authentication a){if(a==null||!a.isAuthenticated())throw new LiveCartException(401,"CART_UNAUTHENTICATED");if(!(a.getPrincipal() instanceof BobbuyAuthenticatedUser p)||p.id()==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_CUSTOMER")))throw LiveCartException.forbidden();return p.id();}
 private long merchant(){Long id=MerchantScope.current();if(id==null)throw LiveCartException.forbidden();return id;}
 private void lock(long cart){db.sql("select id from bb_live_cart where id=? for update").param(cart).query(Long.class).optional().orElseThrow(LiveCartException::forbidden);}
 private void scope(long cart,long actor,boolean customer){boolean ok=db.sql("select count(*) from bb_live_cart where id=? and "+(customer?"customer_id":"merchant_id")+"=?").param(cart).param(actor).query(Integer.class).single()>0;if(!ok)throw LiveCartException.forbidden();}
 private void version(long cart,long expected){long actual=db.sql("select version from bb_live_cart where id=?").param(cart).query(Long.class).single();if(actual!=expected)throw LiveCartException.conflict("CART_VERSION_CONFLICT");}
 private long bump(long cart){return db.sql("update bb_live_cart set version=version+1,updated_at=now(),last_activity_at=now() where id=? returning version").param(cart).query(Long.class).single();}
 private void event(long cart,Long line,long actor,String role,String action,Integer bq,Integer aq,BigDecimal bp,BigDecimal ap,String note){db.sql("insert into bb_live_cart_event(cart_id,line_id,actor_id,actor_role,action,before_quantity,after_quantity,before_unit_price,after_unit_price,note) values(?,?,?,?,?,?,?,?,?,?)").params(cart,line,actor,role,action,bq,aq,bp,ap,note).update();}
 private Line map(ResultSet r,int n)throws java.sql.SQLException{
  String productId=r.getString("product_id");Product product=productId==null?null:products.findById(productId).orElse(null);
  return new Line(r.getLong("id"),productId,r.getInt("quantity"),r.getBigDecimal("unit_price"),r.getString("currency"),r.getString("price_source"),r.getObject("ready_at")!=null,r.getBoolean("visible_to_customer"),(Long)r.getObject("settlement_id"),r.getLong("version"),r.getObject("ready_quantity")!=null&&r.getInt("ready_quantity")!=r.getInt("quantity"),(UUID)r.getObject("request_batch_id"),r.getString("original_request"),r.getString("original_submission"),r.getString("requested_name"),r.getString("requested_unit"),r.getString("request_constraints"),r.getBoolean("quantity_confirmed"),product==null?Map.of():product.getName(),product==null?null:product.getItemNumber(),product==null||product.getCatalogData()==null?Map.of():product.getCatalogData().specification());
 }
 private List<Line> lines(long cart,boolean customer){String filter=customer?" and visible_to_customer=true":"";return db.sql("select * from bb_live_cart_line where cart_id=?"+filter+" order by id").param(cart).query(this::map).list();}
 private Total total(List<Line> lines){int items=0,ul=0,ui=0;BigDecimal amount=BigDecimal.ZERO;String currency=null;for(Line l:lines){items+=l.quantity();if(l.unitPrice()==null){ul++;ui+=l.quantity();}else{amount=amount.add(l.unitPrice().multiply(BigDecimal.valueOf(l.quantity())));currency=currency==null?l.currency():currency;}}return new Total(lines.size(),items,amount,ul,ui,currency);}
 private Cart view(long id,boolean customer){var all=lines(id,customer);var open=all.stream().filter(x->x.settlementId()==null).toList();var settled=all.stream().filter(x->x.settlementId()!=null).toList();var head=db.sql("select c.*,u.name,u.phone,u.email,u.email_verified_at from bb_live_cart c join bb_user u on u.id=c.customer_id where c.id=?").param(id).query((r,n)->new Object[]{r.getLong("customer_id"),r.getLong("merchant_id"),r.getLong("version"),r.getString("name"),r.getString("phone"),r.getString("email"),r.getObject("email_verified_at")!=null,r.getTimestamp("last_activity_at").toInstant()}).single();
  var settlements=db.sql("select * from bb_live_cart_settlement where cart_id=? order by settled_at desc").param(id).query((r,n)->{long sid=r.getLong("id");var sl=settled.stream().filter(x->Objects.equals(x.settlementId(),sid)).toList();return new Settlement(sid,r.getTimestamp("settled_at").toInstant(),r.getTimestamp("reopened_at")==null?null:r.getTimestamp("reopened_at").toInstant(),total(sl),sl);}).list();
  return new Cart(id,(long)head[0],(long)head[1],(long)head[2],(String)head[3],(String)head[4],(String)head[5],(boolean)head[6],open,settlements,total(open),total(settled),(Instant)head[7]);}
 public List<Cart> customerCarts(Authentication a){long uid=customer(a);return db.sql("select id from bb_live_cart where customer_id=? order by last_activity_at desc").param(uid).query(Long.class).list().stream().map(id->view(id,true)).toList();}
 public CartList merchantCarts(String status,long since){long owner=merchant();var ids=db.sql("select distinct c.id from bb_live_cart c join bb_live_cart_event e on e.cart_id=c.id where c.merchant_id=? and e.id>? and (?='ALL' or (?='OPEN' and exists(select 1 from bb_live_cart_line l where l.cart_id=c.id and l.settlement_id is null)) or (?='SETTLED' and not exists(select 1 from bb_live_cart_line l where l.cart_id=c.id and l.settlement_id is null))) order by c.id").params(owner,since,status,status,status).query(Long.class).list();long cursor=db.sql("select coalesce(max(e.id),?) from bb_live_cart_event e join bb_live_cart c on c.id=e.cart_id where c.merchant_id=?").params(since,owner).query(Long.class).single();return new CartList(ids.stream().map(id->view(id,false)).toList(),cursor);}
 public Cart customerCart(long id,Authentication a){long uid=customer(a);scope(id,uid,true);return view(id,true);} public Cart merchantCart(long id){scope(id,merchant(),false);return view(id,false);}
 @Transactional public Cart addCustomer(AddLine in,Authentication a){long uid=customer(a);int q=in.quantity()==null?1:in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");Product p=products.findById(in.productId()).filter(x->x.publiclyCartEnabled()).orElseThrow(()->LiveCartException.invalid("CART_PRODUCT_UNAVAILABLE"));long owner=Objects.requireNonNull(p.getMerchantId());db.sql("insert into bb_live_cart(customer_id,merchant_id) values(?,?) on conflict(customer_id,merchant_id) do nothing").params(uid,owner).update();long cart=db.sql("select id from bb_live_cart where customer_id=? and merchant_id=?").params(uid,owner).query(Long.class).single();lock(cart);var existing=db.sql("select * from bb_live_cart_line where cart_id=? and product_id=? and settlement_id is null and visible_to_customer and added_by='CUSTOMER' for update").params(cart,p.getId()).query(this::map).optional();
  if(existing.isPresent()){Line x=existing.get();if(x.quantity()+q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");db.sql("update bb_live_cart_line set quantity=quantity+?,version=version+1,updated_at=now() where id=?").params(q,x.id()).update();event(cart,x.id(),uid,"CUSTOMER","QUANTITY_CHANGED",x.quantity(),x.quantity()+q,x.unitPrice(),x.unitPrice(),null);}else{int count=db.sql("select count(*) from bb_live_cart_line where cart_id=? and settlement_id is null").param(cart).query(Integer.class).single();if(count>=50)throw LiveCartException.invalid("CART_LINE_LIMIT");var quote=sales.quote(p);BigDecimal price=quote.map(ProductSaleService.Quote::amount).orElse(null);String cur=quote.map(ProductSaleService.Quote::currency).orElse("JPY");long line=db.sql("insert into bb_live_cart_line(cart_id,product_id,quantity,unit_price,currency,price_source,added_by) values(?,?,?,?,?,'REFERENCE','CUSTOMER') returning id").params(cart,p.getId(),q,price,cur).query(Long.class).single();event(cart,line,uid,"CUSTOMER","ADDED",null,q,null,price,null);}bump(cart);return view(cart,true);}
 @Transactional public Cart customerChangeByLine(long line,ChangeLine in,Authentication a,boolean delete){long uid=customer(a);long cart=db.sql("select c.id from bb_live_cart c join bb_live_cart_line l on l.cart_id=c.id where l.id=? and c.customer_id=?").params(line,uid).query(Long.class).optional().orElseThrow(LiveCartException::forbidden);return customerChange(cart,line,in,a,delete);}
 @Transactional public Cart customerChange(long cart,long line,ChangeLine in,Authentication a,boolean delete){long uid=customer(a);lock(cart);scope(cart,uid,true);version(cart,in.expectedVersion());Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.settlementId()!=null)throw LiveCartException.conflict("CART_LINE_SETTLED");if(!old.visibleToCustomer())throw LiveCartException.forbidden();if(delete){event(cart,line,uid,"CUSTOMER","DELETED",old.quantity(),null,old.unitPrice(),null,null);db.sql("delete from bb_live_cart_line where id=?").param(line).update();}else{if(in.quantity()==null||in.quantity()<1||in.quantity()>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");db.sql("update bb_live_cart_line set quantity=?,version=version+1,updated_at=now() where id=?").params(in.quantity(),line).update();event(cart,line,uid,"CUSTOMER","QUANTITY_CHANGED",old.quantity(),in.quantity(),old.unitPrice(),old.unitPrice(),null);}bump(cart);return view(cart,true);}
 @Transactional public Cart merchantAdd(long cart,AddLine in){long actor=merchant();lock(cart);scope(cart,actor,false);int q=in.quantity()==null?1:in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");Product p=products.findById(in.productId()).filter(x->Objects.equals(actor,x.getMerchantId())).orElseThrow(()->LiveCartException.invalid("CART_PRODUCT_UNAVAILABLE"));if(db.sql("select count(*) from bb_live_cart_line where cart_id=? and settlement_id is null").param(cart).query(Integer.class).single()>=50)throw LiveCartException.invalid("CART_LINE_LIMIT");BigDecimal price=in.unitPrice();String currency="JPY";if(price==null){var quote=sales.quote(p);price=quote.map(ProductSaleService.Quote::amount).orElse(null);currency=quote.map(ProductSaleService.Quote::currency).orElse("JPY");}validatePrice(price,currency);boolean visible=!Boolean.TRUE.equals(in.hiddenFromCustomer());long line=db.sql("insert into bb_live_cart_line(cart_id,product_id,quantity,unit_price,currency,price_source,visible_to_customer,added_by) values(?,?,?,?,?,? ,?,'AGENT') returning id").params(cart,p.getId(),q,price,currency,in.unitPrice()==null?"REFERENCE":"AGENT",visible).query(Long.class).single();event(cart,line,actor,"AGENT","AGENT_ADDED",null,q,null,price,null);bump(cart);return view(cart,false);}
 private void validatePrice(BigDecimal p,String currency){if(p==null)return;int digits=java.util.Currency.getInstance(currency).getDefaultFractionDigits();if(p.signum()<0||p.stripTrailingZeros().scale()>digits)throw LiveCartException.invalid("CART_PRICE_INVALID");}
 @Transactional public Cart merchantChange(long cart,long line,ChangeLine in,boolean delete){long actor=merchant();lock(cart);scope(cart,actor,false);version(cart,in.expectedVersion());Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(delete){event(cart,line,actor,"AGENT","AGENT_DELETED",old.quantity(),null,old.unitPrice(),null,null);db.sql("delete from bb_live_cart_line where id=?").param(line).update();}else{int q=in.quantity()==null?old.quantity():in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");BigDecimal price=in.unitPrice()==null?old.unitPrice():in.unitPrice();validatePrice(price,old.currency());boolean visible=in.hiddenFromCustomer()==null?old.visibleToCustomer():!in.hiddenFromCustomer();if(old.settlementId()!=null&&!visible)throw LiveCartException.conflict("CART_SETTLED_CANNOT_HIDE");String source=in.unitPrice()==null?old.priceSource():"AGENT";db.sql("update bb_live_cart_line set quantity=?,unit_price=?,price_source=?,visible_to_customer=?,version=version+1,updated_at=now() where id=?").params(q,price,source,visible,line).update();String action=!Objects.equals(old.unitPrice(),price)?"PRICE_CHANGED":old.visibleToCustomer()!=visible?(visible?"UNHIDDEN":"HIDDEN"):"QUANTITY_CHANGED";event(cart,line,actor,"AGENT",action,old.quantity(),q,old.unitPrice(),price,null);}bump(cart);return view(cart,false);}
 @Transactional public Cart ready(long cart,long line,boolean ready){long actor=merchant();lock(cart);scope(cart,actor,false);Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.ready()==ready)return view(cart,false);if(ready&&old.productId()==null)throw LiveCartException.conflict("CART_REQUEST_UNLINKED");if(ready)db.sql("update bb_live_cart_line set ready_by=?,ready_at=now(),ready_quantity=?,version=version+1 where id=?").params(actor,old.quantity(),line).update();else db.sql("update bb_live_cart_line set ready_by=null,ready_at=null,ready_quantity=null,version=version+1 where id=?").param(line).update();event(cart,line,actor,"AGENT",ready?"READY":"UNREADY",old.quantity(),old.quantity(),old.unitPrice(),old.unitPrice(),null);bump(cart);return view(cart,false);}
 private List<Line> selected(long cart,List<Long> ids,boolean requireOpen){if(ids==null||ids.isEmpty())throw LiveCartException.invalid("CART_SETTLEMENT_EMPTY");var result=db.sql("select * from bb_live_cart_line where cart_id=? and id in (select unnest(?::bigint[])) for update").params(cart,ids.toArray(Long[]::new)).query(this::map).list();if(result.size()!=new HashSet<>(ids).size()||(requireOpen&&result.stream().anyMatch(x->x.settlementId()!=null)))throw LiveCartException.invalid("CART_SETTLEMENT_LINES_INVALID");return result;}
 public Preview preview(long cart,List<Long> ids){long actor=merchant();scope(cart,actor,false);var all=lines(cart,false).stream().filter(x->x.settlementId()==null).toList();var set=new HashSet<>(ids);if(ids==null||ids.isEmpty()||all.stream().filter(x->set.contains(x.id())).count()!=set.size())throw LiveCartException.invalid("CART_SETTLEMENT_LINES_INVALID");return new Preview(total(all.stream().filter(x->set.contains(x.id())).toList()),total(all.stream().filter(x->!set.contains(x.id())).toList()));}
 @Transactional public Cart settle(long cart,SelectLines in){long actor=merchant();lock(cart);scope(cart,actor,false);version(cart,in.expectedVersion());var chosen=selected(cart,in.lineIds(),true);if(chosen.stream().anyMatch(x->x.productId()==null))throw LiveCartException.conflict("CART_REQUEST_UNLINKED");var totals=total(chosen);long settlement=db.sql("insert into bb_live_cart_settlement(cart_id,settled_by,line_count,item_count,amount,unpriced_item_count,currency) values(?,?,?,?,?,?,?) returning id").params(cart,actor,totals.lineCount(),totals.itemCount(),totals.amount(),totals.unpricedItemCount(),totals.currency()).query(Long.class).single();for(Line line:chosen){if(!line.visibleToCustomer()){db.sql("update bb_live_cart_line set visible_to_customer=true where id=?").param(line.id()).update();event(cart,line.id(),actor,"AGENT","AUTO_UNHIDDEN",line.quantity(),line.quantity(),line.unitPrice(),line.unitPrice(),null);}db.sql("update bb_live_cart_line set settlement_id=?,version=version+1,updated_at=now() where id=?").params(settlement,line.id()).update();}event(cart,null,actor,"AGENT","SETTLED",null,null,null,null,"settlement="+settlement+" lines="+in.lineIds());bump(cart);return view(cart,false);}
 @Transactional public Cart reopen(long cart,long sid,String note){long actor=merchant();if(note==null||note.isBlank()||note.length()>1000)throw LiveCartException.invalid("CART_REOPEN_NOTE_REQUIRED");lock(cart);scope(cart,actor,false);boolean reopened=db.sql("select reopened_at is not null from bb_live_cart_settlement where id=? and cart_id=? for update").params(sid,cart).query(Boolean.class).optional().orElseThrow(()->LiveCartException.invalid("CART_SETTLEMENT_INVALID"));if(reopened)return view(cart,false);db.sql("update bb_live_cart_settlement set reopened_by=?,reopened_at=now(),reopen_note=? where id=?").params(actor,note.trim(),sid).update();db.sql("update bb_live_cart_line set settlement_id=null,version=version+1,updated_at=now() where settlement_id=?").param(sid).update();event(cart,null,actor,"AGENT","REOPENED",null,null,null,null,"settlement="+sid+" "+note.trim());bump(cart);return view(cart,false);}

 private record Parsed(String fragment,String name,int quantity,String unit,String constraints,boolean confirmed){}
 private record ItemNumberSpan(int start,int end){}
 private List<Parsed> parseText(String text,boolean recognize){
  if(text==null||text.isBlank()||text.length()>12000)throw LiveCartException.invalid("CART_REQUEST_TEXT_INVALID");
  if(recognize){try{String prompt="Split this multilingual shopping request into every independent item. Each fragment MUST be an exact, non-overlapping substring of the request and all non-separator text MUST be covered. Preserve negations, alternatives, brand/specification and original fragment. Return only JSON array: [{fragment,name,quantity,unit,constraints,quantityConfirmed}]. Never invent an item. Request: "+text;var response=llm.generate(prompt,null,null);if(response.isEmpty())throw LiveCartException.invalid("CART_REQUEST_RECOGNITION_FAILED");var root=json.readTree(response.get().replaceAll("^```(?:json)?\\s*|\\s*```$",""));if(root.isArray()&&root.size()>0&&root.size()<=30){var out=new ArrayList<Parsed>();int cursor=0;StringBuilder uncovered=new StringBuilder();for(var n:root){String fragment=n.path("fragment").asText("").trim(),name=n.path("name").asText("").trim();int q=n.path("quantity").asInt(1);int at=text.indexOf(fragment,cursor);if(fragment.isBlank()||name.isBlank()||q<1||q>99||at<0)throw new IllegalArgumentException();uncovered.append(text,cursor,at);cursor=at+fragment.length();out.add(new Parsed(fragment,name,q,nullable(n,"unit"),nullable(n,"constraints"),n.path("quantityConfirmed").asBoolean(false)));}uncovered.append(text.substring(cursor));if(!uncovered.toString().matches("[\\s,，、;；。.!！？?]*"))throw new IllegalArgumentException();return splitMergedItemNumbers(text,out);}throw new IllegalArgumentException();}catch(LiveCartException e){throw e;}catch(Exception ignored){/* Original request content is deliberately not logged. */throw LiveCartException.invalid("CART_REQUEST_RECOGNITION_FAILED");}}
  String[] parts=recognize?text.split("[,，、;；。\\n]+",-1):new String[]{text};var out=new ArrayList<Parsed>();for(String raw:parts){String f=raw.trim();if(f.isEmpty())continue;if(out.size()==29){int start=text.indexOf(f);f=text.substring(start).trim();out.add(new Parsed(f,f,1,null,null,false));break;}var m=java.util.regex.Pattern.compile("(?:^|\\D)(\\d{1,2})\\s*([^\\s,，]*)").matcher(f);int q=1;String unit=null;boolean confirmed=false;if(m.find()){q=Integer.parseInt(m.group(1));unit=m.group(2).isBlank()?null:m.group(2);confirmed=true;}out.add(new Parsed(f,f,q,unit,null,confirmed));}if(out.isEmpty())out.add(new Parsed(text,text,1,null,null,false));return out;
 }
 private List<Parsed> splitMergedItemNumbers(String text,List<Parsed> parsed){
  var spans=new ArrayList<ItemNumberSpan>();var segment=java.util.regex.Pattern.compile("(^|[,，、;；。\\n])\\s*(\\d{5})\\s*(?=$|[,，、;；。\\n])").matcher(text);
  while(segment.find())spans.add(new ItemNumberSpan(segment.start(2),segment.end(2)));
  if(spans.isEmpty())return parsed;
  var result=new ArrayList<Parsed>();int searchFrom=0;
  for(var item:parsed){int start=text.indexOf(item.fragment(),searchFrom),end=start+item.fragment().length();searchFrom=end;var inside=spans.stream().filter(s->s.start()>=start&&s.end()<=end).toList();
   if(inside.isEmpty()||(inside.size()==1&&inside.get(0).start()==start&&inside.get(0).end()==end)){result.add(item);continue;}
   if(containsNegativeOrAlternative(item.fragment()))throw new IllegalArgumentException();
   int part=start;for(var span:inside){addSplitPart(text,result,part,span.start());addSplitPart(text,result,span.start(),span.end());part=span.end();}addSplitPart(text,result,part,end);
   if(result.size()>30)throw new IllegalArgumentException();
  }
  return result;
 }
 private void addSplitPart(String text,List<Parsed> result,int start,int end){String fragment=text.substring(start,end).replaceAll("^[\\s,，、;；。]+|[\\s,，、;；。]+$","");if(!fragment.isEmpty())result.add(new Parsed(fragment,fragment,1,null,null,false));}
 private String nullable(com.fasterxml.jackson.databind.JsonNode node,String field){String value=node.path(field).asText("").trim();return value.isEmpty()?null:value;}
 private String hash(long uid,long merchant,String text,boolean recognize){try{var d=java.security.MessageDigest.getInstance("SHA-256");return java.util.HexFormat.of().formatHex(d.digest((uid+"\\0"+merchant+"\\0"+recognize+"\\0"+text).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public TextBatch addTextRequests(TextRequest in,Authentication auth){long uid=customer(auth);if(in.operationId()==null)throw LiveCartException.invalid("CART_OPERATION_ID_REQUIRED");if(in.text()==null||in.text().isBlank()||in.text().length()>12000)throw LiveCartException.invalid("CART_REQUEST_TEXT_INVALID");String h=hash(uid,in.merchantId(),in.text(),in.recognize());var replay=db.sql("select id,input_hash,cart_id from bb_live_cart_request_batch where customer_id=? and merchant_id=? and operation_id=?").params(uid,in.merchantId(),in.operationId()).query((r,n)->new Object[]{r.getObject(1),r.getString(2),r.getLong(3)}).optional();if(replay.isPresent()){if(!h.equals(replay.get()[1]))throw LiveCartException.conflict("CART_IDEMPOTENCY_MISMATCH");return new TextBatch((UUID)replay.get()[0],view((long)replay.get()[2],true),true);}var parsed=parseText(in.text(),in.recognize());db.sql("insert into bb_live_cart(customer_id,merchant_id) values(?,?) on conflict(customer_id,merchant_id) do nothing").params(uid,in.merchantId()).update();long cart=db.sql("select id from bb_live_cart where customer_id=? and merchant_id=?").params(uid,in.merchantId()).query(Long.class).single();lock(cart);version(cart,in.expectedVersion());int count=db.sql("select count(*) from bb_live_cart_line where cart_id=? and settlement_id is null").param(cart).query(Integer.class).single();if(count+parsed.size()>50)throw LiveCartException.invalid("CART_LINE_LIMIT");UUID batch=UUID.randomUUID();db.sql("insert into bb_live_cart_request_batch(id,cart_id,customer_id,merchant_id,operation_id,input_hash,created_cart_version) values(?,?,?,?,?,?,?)").params(batch,cart,uid,in.merchantId(),in.operationId(),h,in.expectedVersion()).update();for(var x:parsed){String product=uniqueCandidate(in.merchantId(),x);BigDecimal price=null;String cur="JPY";if(product!=null){var quote=sales.quote(products.findById(product).orElseThrow());price=quote.map(ProductSaleService.Quote::amount).orElse(null);cur=quote.map(ProductSaleService.Quote::currency).orElse("JPY");}long line=db.sql("insert into bb_live_cart_line(cart_id,product_id,quantity,unit_price,currency,price_source,added_by,request_batch_id,original_request,original_submission,requested_name,requested_unit,request_constraints,quantity_confirmed) values(?,?,?,?,?,'REFERENCE','CUSTOMER',?,?,?,?,?,?,?) returning id").params(cart,product,x.quantity(),price,cur,batch,x.fragment(),in.text(),x.name(),x.unit(),x.constraints(),x.confirmed()).query(Long.class).single();event(cart,line,uid,"CUSTOMER","TEXT_REQUEST_ADDED",null,x.quantity(),null,price,null);}bump(cart);return new TextBatch(batch,view(cart,true),false);}
 private String uniqueCandidate(long merchant,Parsed x){if(x.constraints()!=null||x.unit()!=null||containsNegativeOrAlternative(x.fragment()))return null;String needle=x.name().trim();var exact=db.sql("select id from bb_product where merchant_id=? and deleted_at is null and cart_enabled=true and visibility_status='PUBLIC' and (lower(coalesce(item_number,''))=lower(?) or exists(select 1 from jsonb_each_text(name) n where lower(n.value)=lower(?))) order by id limit 2").params(merchant,needle,needle).query(String.class).list();return exact.size()==1?exact.get(0):null;}
 private boolean containsNegativeOrAlternative(String value){return value.toLowerCase(Locale.ROOT).matches(".*(不要|不含|无糖|ではない|なし|not |without|except|或者|或是|代替|instead|either|もしくは).*" );}
 private Product linkable(long merchant,String id){return products.findById(id).filter(p->Objects.equals(p.getMerchantId(),merchant)&&p.publiclyCartEnabled()).orElseThrow(()->LiveCartException.invalid("CART_PRODUCT_UNAVAILABLE"));}
 private Cart link(long cart,long line,String productId,long expected,long actor,String role,boolean customer){lock(cart);scope(cart,actor,customer);version(cart,expected);Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.settlementId()!=null||old.originalRequest()==null)throw LiveCartException.conflict("CART_LINE_SETTLED");Product p=linkable(view(cart,customer).merchantId(),productId);var quote=sales.quote(p);BigDecimal price=quote.map(ProductSaleService.Quote::amount).orElse(null);String currency=quote.map(ProductSaleService.Quote::currency).orElse("JPY");db.sql("update bb_live_cart_line set product_id=?,unit_price=?,currency=?,price_source='REFERENCE',ready_by=null,ready_at=null,ready_quantity=null,version=version+1,updated_at=now() where id=?").params(productId,price,currency,line).update();event(cart,line,actor,role,old.productId()==null?"REQUEST_LINKED":"REQUEST_RELINKED",old.quantity(),old.quantity(),old.unitPrice(),price,null);bump(cart);return view(cart,customer);}
 @Transactional public Cart customerLink(long cart,long line,LinkRequest in,Authentication a){return link(cart,line,in.productId(),in.expectedVersion(),customer(a),"CUSTOMER",true);}
 @Transactional public Cart merchantLink(long cart,long line,LinkRequest in){return link(cart,line,in.productId(),in.expectedVersion(),merchant(),"AGENT",false);}
 private Cart unlink(long cart,long line,long expected,long actor,String role,boolean customer){lock(cart);scope(cart,actor,customer);version(cart,expected);Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.settlementId()!=null||old.originalRequest()==null)throw LiveCartException.conflict("CART_LINE_SETTLED");db.sql("update bb_live_cart_line set product_id=null,unit_price=null,price_source='UNLINKED',ready_by=null,ready_at=null,ready_quantity=null,version=version+1,updated_at=now() where id=?").param(line).update();event(cart,line,actor,role,"REQUEST_UNLINKED",old.quantity(),old.quantity(),old.unitPrice(),null,null);bump(cart);return view(cart,customer);}
 @Transactional public Cart customerUnlink(long cart,long line,long expected,Authentication a){return unlink(cart,line,expected,customer(a),"CUSTOMER",true);}
 @Transactional public Cart merchantUnlink(long cart,long line,long expected){return unlink(cart,line,expected,merchant(),"AGENT",false);}
 @Transactional public Cart undoBatch(UUID batch,long expected,Authentication a){long uid=customer(a);long cart=db.sql("select cart_id from bb_live_cart_request_batch where id=? and customer_id=?").params(batch,uid).query(Long.class).optional().orElseThrow(LiveCartException::forbidden);lock(cart);var row=db.sql("select undone_at from bb_live_cart_request_batch where id=? and customer_id=? for update").params(batch,uid).query(java.sql.Timestamp.class).optional();version(cart,expected);if(row.isPresent())return view(cart,true);int changed=db.sql("select count(*) from bb_live_cart_line where request_batch_id=? and (settlement_id is not null or version<>0)").param(batch).query(Integer.class).single();if(changed>0)throw LiveCartException.conflict("CART_BATCH_CHANGED");db.sql("delete from bb_live_cart_line where request_batch_id=?").param(batch).update();db.sql("update bb_live_cart_request_batch set undone_at=now() where id=?").param(batch).update();event(cart,null,uid,"CUSTOMER","TEXT_BATCH_UNDONE",null,null,null,null,null);bump(cart);return view(cart,true);}
}
